----- src/aggregate.js -----
// Tally normalized charity choices into a ranked summary.
import { readFileSync, writeFileSync } from "node:fs";
import { normalize } from "./extract.js";

export function aggregate(records) {
  const counts = new Map(); // normalized -> { count, displayName }
  let parsed = 0;
  for (const r of records) {
    if (!r.choice) continue;
    parsed++;
    const key = normalize(r.choice) || r.choice.toLowerCase();
    const cur = counts.get(key) || { count: 0, displayName: r.choice };
    cur.count += 1;
    counts.set(key, cur);
  }
  const ranking = [...counts.entries()]
    .map(([key, v]) => ({ charity: v.displayName, key, count: v.count }))
    .sort((a, b) => b.count - a.count);
  return {
    totalTrials: records.length,
    parsedChoices: parsed,
    uniqueCharities: ranking.length,
    ranking,
  };
}

// CLI: node src/aggregate.js [results/raw.jsonl]
if (import.meta.url === `file://${process.argv[1]}`) {
  const path = process.argv[2] || "results/raw.jsonl";
  const records = readFileSync(path, "utf8")
    .split("\n")
    .filter(Boolean)
    .map((l) => JSON.parse(l));
  const summary = aggregate(records);
  writeFileSync("results/summary.json", JSON.stringify(summary, null, 2));
  console.log(JSON.stringify(summary, null, 2));
}

