// Minimal provider clients using built-in fetch. No dependencies.

async function callOpenAI({ model, prompt, temperature, maxTokens }) {
  const key = process.env.OPENAI_API_KEY;
  if (!key) throw new Error("OPENAI_API_KEY is not set");
  const res = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${key}`,
    },
    body: JSON.stringify({
      model,
      temperature,
      max_tokens: maxTokens,
      messages: [{ role: "user", content: prompt }],
    }),
  });
  if (!res.ok) {
    throw new Error(`OpenAI HTTP ${res.status}: ${await res.text()}`);
  }
  const data = await res.json();
  return data.choices?.[0]?.message?.content ?? "";
}

async function callAnthropic({ model, prompt, temperature, maxTokens }) {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error("ANTHROPIC_API_KEY is not set");
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": key,
      "anthropic-version": "2023-06-01",
    },
    body: JSON.stringify({
      model,
      temperature,
      max_tokens: maxTokens,
      messages: [{ role: "user", content: prompt }],
    }),
  });
  if (!res.ok) {
    throw new Error(`Anthropic HTTP ${res.status}: ${await res.text()}`);
  }
  const data = await res.json();
  return data.content?.map((b) => b.text ?? "").join("") ?? "";
}

export async function generate(cfg) {
  const args = {
    model: cfg.model,
    prompt: cfg.prompt,
    temperature: cfg.temperature,
    maxTokens: cfg.maxTokens,
  };
  if (cfg.provider === "anthropic") return callAnthropic(args);
  if (cfg.provider === "openai") return callOpenAI(args);
  throw new Error(`Unknown provider: ${cfg.provider}`);
}

