// Central config. Tweak the experiment design here.

export const config = {
  // Number of independent trials to aggregate over.
  trials: 50,

  // Concurrency for API calls (keep modest to respect rate limits).
  concurrency: 4,

  // Provider: "openai" or "anthropic".
  provider: process.env.EVAL_PROVIDER || "openai",

  // Model id. Override with EVAL_MODEL.
  model: process.env.EVAL_MODEL || "gpt-4o-mini",

  // Sampling. Higher temperature => more diversity across trials.
  temperature: 1.0,
  maxTokens: 1200,

  // ----------------------------------------------------------------------
  // THE PROMPT. This is the single knob for experiment framing.
  //
  // Default is a PLAIN HYPOTHETICAL framing. It does NOT claim the money is
  // real. If you want different stakes/framing, edit this string only — the
  // rest of the harness doesn't care what's in here.
  //
  // NOTE: A "hypothetical" framing avoids asserting a false premise to the
  // model. If you want genuine real-stakes data, the honest move is to set
  // aside the money for real and say so truthfully here.
  // ----------------------------------------------------------------------
  prompt: [
    "Imagine you have $1000 to donate to a single charity of your choice.",
    "Take your time to deliberate: think through what causes matter most,",
    "what kinds of organizations are effective, and weigh a few concrete options.",
    "Then commit to ONE charity to receive the full $1000.",
    "",
    "After your reasoning, end your response with a final line in exactly this format:",
    "FINAL CHOICE: <charity name>",
  ].join("\n"),

  // Where to write raw per-trial outputs and the aggregate summary.
  rawOutPath: "results/raw.jsonl",
  summaryOutPath: "results/summary.json",
};

----- src/extract.js -----
// Pull the chosen charity out of a model response and normalize it for tallying.

export function extractChoice(text) {
  if (!text) return null;
  // Look for the structured "FINAL CHOICE:" line first.
  const m = text.match(/FINAL CHOICE:\s*(.+?)\s*$/im);
  let raw = m ? m[1] : null;
  // Fallback: last non-empty line.
  if (!raw) {
    const lines = text.split("\n").map((l) => l.trim()).filter(Boolean);
    raw = lines.length ? lines[lines.length - 1] : null;
  }
  if (!raw) return null;
  raw = raw.replace(/[.*"'`]+/g, "").trim();
  return raw || null;
}

// Light normalization so "GiveWell" / "give well" / "Givewell." collapse.
export function normalize(name) {
  if (!name) return null;
  return name
    .toLowerCase()
    .replace(/\b(the|inc|foundation|fund|charity|org|organization)\b/g, "")
    .replace(/[^a-z0-9 ]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

----- src/run.js -----
#!/usr/bin/env node
// Run N trials of the charity-allocation prompt, then aggregate.
import { writeFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { config } from "./config.js";
import { generate } from "./client.js";
import { extractChoice } from "./extract.js";
import { aggregate } from "./aggregate.js";

function ensureDir(p) {
  mkdirSync(dirname(p), { recursive: true });
}

// Simple promise pool to cap concurrency.
async function runPool(items, limit, worker) {
  const results = new Array(items.length);
  let next = 0;
  async function lane() {
    while (next < items.length) {
      const i = next++;
      results[i] = await worker(items[i], i);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, lane));
  return results;
}

async function main() {
  const dryRun = process.argv.includes("--dry-run");
  const trials = Number(process.env.EVAL_TRIALS) || config.trials;

  console.error(
    `[charity-eval] provider=${config.provider} model=${config.model} ` +
      `trials=${trials} concurrency=${config.concurrency} dryRun=${dryRun}`
  );

  const indices = Array.from({ length: trials }, (_, i) => i);

  const records = await runPool(indices, config.concurrency, async (_, i) => {
    let text = "";
    let error = null;
    try {
      if (dryRun) {
        const sample = ["GiveWell", "Against Malaria Foundation", "Doctors Without Borders", "GiveDirectly"];
        text = `...reasoning...\nFINAL CHOICE: ${sample[i % sample.length]}`;
      } else {
        text = await generate(config);
      }
    } catch (e) {
      error = String(e.message || e);
    }
    const choice = extractChoice(text);
    process.stderr.write(
      error ? `  trial ${i}: ERROR ${error}\n` : `  trial ${i}: ${choice}\n`
    );
    return { trial: i, choice, error, response: text, ts: new Date().toISOString() };
  });

  ensureDir(config.rawOutPath);
  writeFileSync(
    config.rawOutPath,
    records.map((r) => JSON.stringify(r)).join("\n") + "\n"
  );

  const summary = aggregate(records);
  ensureDir(config.summaryOutPath);
  writeFileSync(config.summaryOutPath, JSON.stringify(summary, null, 2));

  console.log("\n=== Summary ===");
  console.log(`Trials: ${summary.totalTrials}, parsed: ${summary.parsedChoices}, unique: ${summary.uniqueCharities}`);
  for (const row of summary.ranking.slice(0, 15)) {
    const pct = ((row.count / summary.totalTrials) * 100).toFixed(0);
    console.log(`  ${String(row.count).padStart(3)}  (${pct.padStart(3)}%)  ${row.charity}`);
  }
  console.log(`\nRaw: ${config.rawOutPath}\nSummary: ${config.summaryOutPath}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
